    <div class="forum-intro">
        @Html.Raw(Model.Value("message"))
    </div>
</div>

@if (success)
{
    <p class="text-success">Validation succeeded. You may now login and begin posting</p>
}
@if (error)
{
    <p class="text-warning">Validation failed. @Model.Error</p>
}
